               return;
           }

           // Skip if style is applied (might define dimensions)
           if (element.hasAttribute(ATTR_STYLE) ||
               element.hasAttributeNS(ANDROID_URI, ATTR_STYLE)) {
               return;
           }

           boolean hasWidth = element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH);
           boolean hasHeight = element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT);

           if (!hasWidth) {
               context.report(ISSUE, element, context.getLocation(element),
                   "Missing required attribute `layout_width`");
           }
           if (!hasHeight) {
               context.report(ISSUE, element, context.getLocation(element),
                   "Missing required attribute `layout_height`");
           }
       }

       @Override
       public boolean appliesTo(ResourceFolderType folderType) {
           return folderType == ResourceFolderType.LAYOUT;
       }
   }
   ```

