public static boolean hasLayoutVariations(File file) {
    File parent = file.getParentFile();
    if (parent == null) return false;
    String parentName = parent.getName();
    int dashIndex = parentName.indexOf('-');
    String baseName = dashIndex == -1 ? parentName : parentName.substring(0, dashIndex);

    File resDir = parent.getParentFile();
    if (resDir == null) return false;

    File[] siblings = resDir.listFiles();
    if (siblings == null) return false;

    String fileName = file.getName();
    for (File sibling : siblings) {
        if (sibling.isDirectory() && sibling.getName().startsWith(baseName + "-")) {
            File variation = new File(sibling, fileName);
            if (variation.exists()) {
                return true;
            }
        }
    }
    return false;
}
